import OpenAI from 'openai';

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

interface ProductInput {
  name: string;
  category: string;
  scentNotes?: string[];
  description: string;
}

export async function generateProductEmbedding(product: ProductInput): Promise<number[]> {
  // Clean and format text payload for dense semantic coverage
  const inputContent = [
    `Product: ${product.name}`,
    `Category: ${product.category}`,
    product.scentNotes ? `Notes: ${product.scentNotes.join(', ')}` : '',
    `Details: ${product.description}`
  ].filter(Boolean).join('\n');

  const response = await openai.embeddings.create({
    model: 'text-embedding-3-small',
    input: inputContent,
    encoding_format: 'float',
  });

  return response.data[0].embedding;
}

import { createClient } from '@supabase/supabase-js';
import Link from 'next/link';

interface RelatedProduct {
  id: number;
  name: string;
  slug: string;
  price: number;
  similarity: number;
}

export async function RelatedProductsSection({ 
  productId, 
  embedding 
}: { 
  productId: number;
  embedding: number[]; 
}) {
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  );

  const { data: recommendations, error } = await supabase.rpc(
    'match_related_products',
    {
      target_embedding: embedding,
      match_threshold: 0.70,
      match_count: 4,
      current_product_id: productId,
    }
  );

  if (error || !recommendations?.length) {
    return null;
  }

  return (
    <section className="mt-16 border-t border-zinc-200 pt-8 dark:border-zinc-800">
      <h3 className="text-lg font-semibold text-zinc-900 dark:text-zinc-100">
        You May Also Like
      </h3>
      <div className="mt-6 grid grid-cols-2 gap-4 sm:grid-cols-4">
        {recommendations.map((item: RelatedProduct) => (
          <Link
            key={item.id}
            href={`/products/${item.slug}`}
            className="group rounded-lg border border-zinc-200 p-4 transition-colors hover:border-zinc-400 dark:border-zinc-800 dark:hover:border-zinc-600"
          >
            <p className="font-medium text-zinc-800 group-hover:text-blue-600 dark:text-zinc-200">
              {item.name}
            </p>
            <p className="mt-1 text-sm text-zinc-500">₹{item.price}</p>
            <span className="mt-2 inline-block text-xs text-emerald-600 dark:text-emerald-400">
              {Math.round(item.similarity * 100)}% Match
            </span>
          </Link>
        ))}
      </div>
    </section>
  );
}
